			function dateToStr(d) {
				var str = "";
				str += d.getFullYear() + "-";
				if (d.getMonth() + 1 < 10) {
					str += "0" + (d.getMonth() + 1) + "-";
				} else {
					str += (d.getMonth() + 1) + "-";
				}
				if (d.getDate() < 10) {
			        str += "0" + d.getDate();
				} else {
				    str += d.getDate();
				}
				return str; 
			}


