			function copyList() {
			    
			    /** @type cpr.data.DataSet */
			    var dsList = app.lookup("dsList");
			    
			    /** @type cpr.data.DataSet */
			    var dsList2 = app.lookup("dsList2");
			    
			    for (var i = dsList2.getRowCount() - 1; i >= 0; i--) {
			        dsList2.deleteRow(i);
			    }
			    
			    dsList2.commit();
			    
			    dsList.copyToDataSet(dsList2);
			    
			    dsList2.commit();
			}

			function deleteAllItems() {
			    
			    /** @type cpr.data.DataSet */        
			    var dsList = app.lookup("dsList2");
			    var rows = dsList.getRowDataRanged();

			    var calendar = app.lookup("cal1");
			    
			    //console.log("rows.length", rows.length);
			    
			    for (var i=0; i < rows.length; i++) {
			        
			        var row = rows[i];
			        
			        var startDate = row["START_DATE"].substr(0, 4) + "-" + row["START_DATE"].substr(4, 2) + "-" + row["START_DATE"].substr(6, 2);
			        var endDate = row["END_DATE"].substr(0, 4) + "-" + row["END_DATE"].substr(4, 2) + "-" + row["END_DATE"].substr(6, 2);

			        //console.log("startDate", startDate);
			        //console.log("endDate", endDate);
			                        
			        /* 선행데이터 생성 */
			        var item = new cpr.controls.CalendarItem(
			            //row["HOLIDAY_NAME"], new Date(row["START_DATE"]), new Date(row["END_DATE"])
			            row["HOLIDAY_NAME"], new Date(startDate), new Date(endDate)
			        );
			        
			        //var item = calendar.findItem({label: row["HOLIDAY_NAME"], start:new Date(startDate), end:new Date(endDate)});
			        var item1 = calendar.findItem(function(item){
			            return moment(item.start).isSame(moment(startDate)) &&
			            moment(item.end).isSame(moment(endDate)) &&
			            (item.label == row["HOLIDAY_NAME"]);
			        });
			        //console.log("item1", item1.label);
			        
			        if (item1 != null) {
			            calendar.deleteItem(item);
			        }
			    }

			    calendar.redraw();
			    
			    /** @type cpr.data.DataSet */
			    var dsList2 = app.lookup("dsList2");
			    
			    for (var i = dsList2.getRowCount() - 1; i >= 0; i--) {
			        dsList2.deleteRow(i);
			    }
			    
			    dsList2.commit();
			    
			}

